PRAGMA journal_mode=WAL;
PRAGMA synchronous=NORMAL;
PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS assets(
 id TEXT PRIMARY KEY,path TEXT NOT NULL,path_key TEXT NOT NULL UNIQUE,root TEXT NOT NULL DEFAULT '',revision TEXT NOT NULL,
 modified INTEGER NOT NULL DEFAULT 0,edited INTEGER NOT NULL DEFAULT 0,rating INTEGER NOT NULL DEFAULT 0,flag TEXT NOT NULL DEFAULT '',
 label TEXT NOT NULL DEFAULT '',tags TEXT NOT NULL DEFAULT '[]',exif TEXT NOT NULL DEFAULT '{}',raw INTEGER NOT NULL DEFAULT 0,
 available INTEGER NOT NULL DEFAULT 1,review TEXT NOT NULL DEFAULT 'unreviewed',capture TEXT NOT NULL DEFAULT '',camera TEXT NOT NULL DEFAULT '',lens TEXT NOT NULL DEFAULT '',added INTEGER NOT NULL,
 small_preview TEXT,medium_preview TEXT,render_revision TEXT NOT NULL DEFAULT '',source_signature TEXT NOT NULL DEFAULT '',metadata_revision TEXT NOT NULL DEFAULT '',hidden INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS assets_root ON assets(root);
CREATE INDEX IF NOT EXISTS assets_capture ON assets(capture,path);
CREATE INDEX IF NOT EXISTS assets_flag ON assets(flag);
CREATE INDEX IF NOT EXISTS assets_rating ON assets(rating);
CREATE INDEX IF NOT EXISTS assets_review ON assets(review);
CREATE INDEX IF NOT EXISTS assets_added ON assets(added);
CREATE TABLE IF NOT EXISTS collections(id TEXT PRIMARY KEY,name TEXT NOT NULL,parent TEXT REFERENCES collections(id) ON DELETE CASCADE,kind TEXT NOT NULL,rules TEXT NOT NULL DEFAULT '[]',mode TEXT NOT NULL DEFAULT 'all');
INSERT OR IGNORE INTO collections(id,name,kind) VALUES('quick','Quick collection','collection');
CREATE TABLE IF NOT EXISTS members(collection_id TEXT REFERENCES collections(id) ON DELETE CASCADE,asset_id TEXT REFERENCES assets(id) ON DELETE CASCADE,position INTEGER NOT NULL,PRIMARY KEY(collection_id,asset_id));
CREATE INDEX IF NOT EXISTS members_asset ON members(asset_id);
CREATE TABLE IF NOT EXISTS state(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS edit_records(path TEXT PRIMARY KEY,json TEXT NOT NULL,modified INTEGER NOT NULL,deleted INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,data TEXT NOT NULL,modified INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,kind TEXT NOT NULL,roots TEXT NOT NULL,status TEXT NOT NULL,completed INTEGER NOT NULL DEFAULT 0,total INTEGER NOT NULL DEFAULT 0,failed INTEGER NOT NULL DEFAULT 0,current TEXT NOT NULL DEFAULT '',error TEXT NOT NULL DEFAULT '',created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS job_items(job_id TEXT NOT NULL,path TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',error TEXT NOT NULL DEFAULT '',PRIMARY KEY(job_id,path));
CREATE TABLE IF NOT EXISTS raw_cache(asset_id TEXT PRIMARY KEY,path TEXT NOT NULL,revision TEXT NOT NULL,local_path TEXT NOT NULL,hash TEXT NOT NULL,size INTEGER NOT NULL,pinned INTEGER NOT NULL DEFAULT 0,used INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS undo(id INTEGER PRIMARY KEY AUTOINCREMENT,data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS suggestions(id TEXT PRIMARY KEY,data TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'pending',modified INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS pins(asset_id TEXT PRIMARY KEY REFERENCES assets(id) ON DELETE CASCADE);
